package data_structures.trees;
import java.util.*;
import java.util.function.*;
import java.math.*;

public class RedBlackTree {
public static class Tree<T> implements Iterable<T>{private static class Node<T>{T value;boolean red;Node<T> left,right,parent;Node(T v,boolean r,Node<T> nil){value=v;red=r;left=right=parent=nil==null?this:nil;}}private final Node<T> nil=new Node<>(null,false,null);private Node<T> root=nil;private final Comparator<T> compare;private int count;public Tree(){this(shared.Compare::defaultCompare);}public Tree(Comparator<T> c){compare=c;}public int size(){return count;}private Node<T> search(T v){Node<T> n=root;while(n!=nil){int c=compare.compare(v,n.value);if(c==0)return n;n=c<0?n.left:n.right;}return nil;}public boolean has(T v){return search(v)!=nil;}public boolean insert(T v){Node<T> p=nil,n=root;while(n!=nil){p=n;int c=compare.compare(v,n.value);if(c==0)return false;n=c<0?n.left:n.right;}n=new Node<>(v,true,nil);n.parent=p;if(p==nil)root=n;else if(compare.compare(v,p.value)<0)p.left=n;else p.right=n;fixInsert(n);count++;return true;}private void rotateLeft(Node<T> n){Node<T> p=n.right;n.right=p.left;if(p.left!=nil)p.left.parent=n;p.parent=n.parent;if(n.parent==nil)root=p;else if(n==n.parent.left)n.parent.left=p;else n.parent.right=p;p.left=n;n.parent=p;}private void rotateRight(Node<T> n){Node<T> p=n.left;n.left=p.right;if(p.right!=nil)p.right.parent=n;p.parent=n.parent;if(n.parent==nil)root=p;else if(n==n.parent.right)n.parent.right=p;else n.parent.left=p;p.right=n;n.parent=p;}private void fixInsert(Node<T> n){while(n.parent.red){Node<T> p=n.parent,g=p.parent;if(p==g.left){Node<T> u=g.right;if(u.red){p.red=u.red=false;g.red=true;n=g;continue;}if(n==p.right){n=p;rotateLeft(n);}n.parent.red=false;g.red=true;rotateRight(g);}else{Node<T> u=g.left;if(u.red){p.red=u.red=false;g.red=true;n=g;continue;}if(n==p.left){n=p;rotateRight(n);}n.parent.red=false;g.red=true;rotateLeft(g);}}root.red=false;}private Node<T> minimum(Node<T> n){while(n.left!=nil)n=n.left;return n;}private void transplant(Node<T> n,Node<T> r){if(n.parent==nil)root=r;else if(n==n.parent.left)n.parent.left=r;else n.parent.right=r;r.parent=n.parent;}public boolean delete(T v){Node<T> target=search(v);if(target==nil)return false;Node<T> removed=target,replacement;boolean wasRed=removed.red;if(target.left==nil){replacement=target.right;transplant(target,replacement);}else if(target.right==nil){replacement=target.left;transplant(target,replacement);}else{removed=minimum(target.right);wasRed=removed.red;replacement=removed.right;if(removed.parent==target)replacement.parent=removed;else{transplant(removed,removed.right);removed.right=target.right;removed.right.parent=removed;}transplant(target,removed);removed.left=target.left;removed.left.parent=removed;removed.red=target.red;}if(!wasRed)fixDelete(replacement);count--;return true;}private void fixDelete(Node<T> n){while(n!=root&&!n.red){if(n==n.parent.left){Node<T> s=n.parent.right;if(s.red){s.red=false;n.parent.red=true;rotateLeft(n.parent);s=n.parent.right;}if(!s.left.red&&!s.right.red){s.red=true;n=n.parent;}else{if(!s.right.red){s.left.red=false;s.red=true;rotateRight(s);s=n.parent.right;}s.red=n.parent.red;n.parent.red=false;s.right.red=false;rotateLeft(n.parent);n=root;}}else{Node<T> s=n.parent.left;if(s.red){s.red=false;n.parent.red=true;rotateRight(n.parent);s=n.parent.left;}if(!s.left.red&&!s.right.red){s.red=true;n=n.parent;}else{if(!s.left.red){s.right.red=false;s.red=true;rotateLeft(s);s=n.parent.left;}s.red=n.parent.red;n.parent.red=false;s.left.red=false;rotateRight(n.parent);n=root;}}}n.red=false;}public int height(){return height(root);}private int height(Node<T> n){return n==nil?0:1+Math.max(height(n.left),height(n.right));}public boolean isValid(){return !root.red&&blackHeight(root)!=-1;}private int blackHeight(Node<T> n){if(n==nil)return 1;if(n.red&&(n.left.red||n.right.red))return -1;int l=blackHeight(n.left),r=blackHeight(n.right);if(l==-1||r==-1||l!=r)return -1;return l+(n.red?0:1);}public List<T> toArray(){List<T> o=new ArrayList<>();walk(root,o);return o;}private void walk(Node<T> n,List<T> o){if(n!=nil){walk(n.left,o);o.add(n.value);walk(n.right,o);}}public Iterator<T> iterator(){return toArray().iterator();}}
}
